CREATE SCHEMA IF NOT EXISTS observability;
COMMENT ON SCHEMA observability IS 'OpenTelemetry governance, service objectives, alerts, incidents, runbooks and learning reviews';

CREATE TABLE observability.services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),service_key varchar(64) NOT NULL CHECK(service_key~'^[a-z][a-z0-9-]{2,62}$'),display_name varchar(120) NOT NULL,owner_team varchar(80) NOT NULL,tier smallint NOT NULL CHECK(tier BETWEEN 0 AND 3),runbook_url text NOT NULL CHECK(runbook_url~'^https://'),status text NOT NULL DEFAULT 'operational' CHECK(status IN('operational','degraded','outage','maintenance')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,service_key));
CREATE INDEX observability_service_status_idx ON observability.services(tenant_id,status,tier);

CREATE TABLE observability.slo_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),service_key varchar(64) NOT NULL,objective_key varchar(80) NOT NULL,version integer NOT NULL CHECK(version>0),indicator_type text NOT NULL CHECK(indicator_type IN('availability','latency','correctness','freshness')),target_bps integer NOT NULL CHECK(target_bps BETWEEN 5000 AND 9999),window_days integer NOT NULL CHECK(window_days BETWEEN 1 AND 90),query jsonb NOT NULL CHECK(jsonb_typeof(query)='object'),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','retired')),created_by uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),activated_at timestamptz,CHECK(approved_by IS NULL OR approved_by<>created_by),UNIQUE(tenant_id,service_key,objective_key,version));
CREATE INDEX observability_slo_definition_idx ON observability.slo_definitions(tenant_id,service_key,state,version DESC);

CREATE TABLE observability.slo_windows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),slo_definition_id uuid NOT NULL REFERENCES observability.slo_definitions(id) ON DELETE RESTRICT,service_key varchar(64) NOT NULL,window_started_at timestamptz NOT NULL,window_ended_at timestamptz NOT NULL,total_events bigint NOT NULL CHECK(total_events>=0),good_events bigint NOT NULL CHECK(good_events BETWEEN 0 AND total_events),availability_bps integer NOT NULL CHECK(availability_bps BETWEEN 0 AND 10000),error_budget_remaining_bps integer NOT NULL CHECK(error_budget_remaining_bps BETWEEN 0 AND 10000),burn_rate numeric(12,4) NOT NULL CHECK(burn_rate>=0),is_current boolean NOT NULL DEFAULT false,calculated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(window_ended_at>window_started_at));
CREATE UNIQUE INDEX observability_current_slo_idx ON observability.slo_windows(tenant_id,slo_definition_id) WHERE is_current;
CREATE INDEX observability_slo_service_idx ON observability.slo_windows(tenant_id,service_key,window_ended_at DESC);

CREATE TABLE observability.alert_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),rule_key varchar(80) NOT NULL,version integer NOT NULL CHECK(version>0),service_key varchar(64) NOT NULL,severity text NOT NULL CHECK(severity IN('sev1','sev2','sev3','sev4')),expression jsonb NOT NULL CHECK(jsonb_typeof(expression)='object'),short_window_minutes integer NOT NULL CHECK(short_window_minutes BETWEEN 1 AND 120),long_window_minutes integer NOT NULL CHECK(long_window_minutes BETWEEN 5 AND 1440),routes jsonb NOT NULL CHECK(jsonb_typeof(routes)='array'),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','muted','retired')),created_by uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(long_window_minutes>short_window_minutes),CHECK(approved_by IS NULL OR approved_by<>created_by),UNIQUE(tenant_id,rule_key,version));

CREATE TABLE observability.alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),rule_id uuid NOT NULL REFERENCES observability.alert_rules(id) ON DELETE RESTRICT,fingerprint char(64) NOT NULL CHECK(fingerprint~'^[a-f0-9]{64}$'),service_key varchar(64) NOT NULL,severity text NOT NULL CHECK(severity IN('sev1','sev2','sev3','sev4')),state text NOT NULL DEFAULT 'firing' CHECK(state IN('firing','acknowledged','silenced','resolved')),labels jsonb NOT NULL CHECK(jsonb_typeof(labels)='object'),annotations jsonb NOT NULL CHECK(jsonb_typeof(annotations)='object'),occurrence_count integer NOT NULL DEFAULT 1 CHECK(occurrence_count>0),first_fired_at timestamptz NOT NULL,last_fired_at timestamptz NOT NULL,acknowledged_by uuid,acknowledged_at timestamptz,resolved_at timestamptz,UNIQUE(tenant_id,fingerprint,state));
CREATE INDEX observability_alert_queue_idx ON observability.alerts(tenant_id,state,severity,last_fired_at DESC) WHERE state IN('firing','acknowledged');

CREATE TABLE observability.incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),number bigint GENERATED ALWAYS AS IDENTITY,title varchar(180) NOT NULL,severity text NOT NULL CHECK(severity IN('sev1','sev2','sev3','sev4')),state text NOT NULL DEFAULT 'detected' CHECK(state IN('detected','triaged','mitigating','monitoring','resolved','closed')),service_key varchar(64) NOT NULL,commander_id uuid,communications_lead_id uuid,impact_summary varchar(500) NOT NULL,public_status text NOT NULL DEFAULT 'investigating' CHECK(public_status IN('investigating','identified','monitoring','resolved')),started_at timestamptz NOT NULL,detected_at timestamptz NOT NULL DEFAULT clock_timestamp(),mitigated_at timestamptz,resolved_at timestamptz,closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,number));
CREATE INDEX observability_incident_queue_idx ON observability.incidents(tenant_id,state,severity,started_at) WHERE state<>'closed';

CREATE TABLE observability.incident_alerts(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),incident_id uuid NOT NULL REFERENCES observability.incidents(id) ON DELETE RESTRICT,alert_id uuid NOT NULL REFERENCES observability.alerts(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,incident_id,alert_id));

CREATE TABLE observability.incident_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),incident_id uuid NOT NULL REFERENCES observability.incidents(id) ON DELETE RESTRICT,event_type varchar(80) NOT NULL,actor_id uuid,summary varchar(500) NOT NULL,payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX observability_incident_event_idx ON observability.incident_events(tenant_id,incident_id,created_at);

CREATE TABLE observability.runbooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),runbook_key varchar(80) NOT NULL,service_key varchar(64) NOT NULL,version integer NOT NULL CHECK(version>0),title varchar(180) NOT NULL,steps jsonb NOT NULL CHECK(jsonb_typeof(steps)='array' AND jsonb_array_length(steps)>0),rollback_steps jsonb NOT NULL CHECK(jsonb_typeof(rollback_steps)='array'),owner_team varchar(80) NOT NULL,last_drilled_at timestamptz,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','retired')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,runbook_key,version));

CREATE TABLE observability.postmortems(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),incident_id uuid NOT NULL REFERENCES observability.incidents(id) ON DELETE RESTRICT,severity text NOT NULL CHECK(severity IN('sev1','sev2','sev3','sev4')),impact text NOT NULL,root_cause text NOT NULL,contributing_factors jsonb NOT NULL CHECK(jsonb_typeof(contributing_factors)='array' AND jsonb_array_length(contributing_factors)>0),lessons jsonb NOT NULL CHECK(jsonb_typeof(lessons)='array'),action_items jsonb NOT NULL CHECK(jsonb_typeof(action_items)='array' AND jsonb_array_length(action_items)>0),commander_id uuid NOT NULL,reviewer_id uuid,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','published')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),published_at timestamptz,CHECK(status<>'published' OR(reviewer_id IS NOT NULL AND reviewer_id<>commander_id)),UNIQUE(tenant_id,incident_id));

CREATE TABLE observability.maintenance_windows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),service_key varchar(64) NOT NULL,title varchar(180) NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,created_by uuid NOT NULL,approved_by uuid NOT NULL,reason varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(ends_at>starts_at),CHECK(created_by<>approved_by));
CREATE INDEX observability_maintenance_window_idx ON observability.maintenance_windows(tenant_id,service_key,starts_at,ends_at);

CREATE TABLE observability.daily_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),metric_date date NOT NULL,open_incidents integer NOT NULL DEFAULT 0 CHECK(open_incidents>=0),paging_alerts integer NOT NULL DEFAULT 0 CHECK(paging_alerts>=0),services_at_risk integer NOT NULL DEFAULT 0 CHECK(services_at_risk>=0),error_budget_remaining_bps integer NOT NULL DEFAULT 10000 CHECK(error_budget_remaining_bps BETWEEN 0 AND 10000),mean_time_to_recover_seconds integer NOT NULL DEFAULT 0 CHECK(mean_time_to_recover_seconds>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,metric_date));

CREATE FUNCTION observability.transition_incident(incident_id uuid,actor_id uuid,next_state text,transition_summary text) RETURNS observability.incidents LANGUAGE plpgsql AS $$DECLARE current_incident observability.incidents;BEGIN SELECT * INTO current_incident FROM observability.incidents WHERE id=incident_id AND tenant_id=NULLIF(current_setting('app.current_tenant_id',true),'')::uuid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'incident_not_found';END IF;IF NOT CASE current_incident.state WHEN 'detected' THEN next_state='triaged' WHEN 'triaged' THEN next_state IN('mitigating','resolved') WHEN 'mitigating' THEN next_state IN('monitoring','resolved') WHEN 'monitoring' THEN next_state IN('mitigating','resolved') WHEN 'resolved' THEN next_state IN('closed','mitigating') ELSE false END THEN RAISE EXCEPTION 'incident_transition_invalid';END IF;UPDATE observability.incidents SET state=next_state,updated_at=clock_timestamp(),mitigated_at=CASE WHEN next_state='monitoring' THEN clock_timestamp() ELSE mitigated_at END,resolved_at=CASE WHEN next_state='resolved' THEN clock_timestamp() ELSE resolved_at END,closed_at=CASE WHEN next_state='closed' THEN clock_timestamp() ELSE closed_at END WHERE id=current_incident.id RETURNING * INTO current_incident;INSERT INTO observability.incident_events(tenant_id,incident_id,event_type,actor_id,summary)VALUES(current_incident.tenant_id,current_incident.id,'state_transition',actor_id,transition_summary);RETURN current_incident;END$$;

CREATE FUNCTION observability.reject_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'observability_evidence_append_only';END$$;
CREATE TRIGGER observability_incident_events_immutable BEFORE UPDATE OR DELETE ON observability.incident_events FOR EACH ROW EXECUTE FUNCTION observability.reject_evidence_mutation();
CREATE TRIGGER observability_postmortems_immutable BEFORE UPDATE OR DELETE ON observability.postmortems FOR EACH ROW WHEN(OLD.status='published') EXECUTE FUNCTION observability.reject_evidence_mutation();

DO $$DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['services','slo_definitions','slo_windows','alert_rules','alerts','incidents','incident_alerts','incident_events','runbooks','postmortems','maintenance_windows','daily_metrics'] LOOP EXECUTE format('ALTER TABLE observability.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE observability.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON observability.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
